// Producer writes four raw original A quadrants, with no A transform/cast.
template <class Element,int BK,class SmemA>
CUTE_DEVICE void psplit_sw128_simt_control_root_future41_fill_a(const Problem& p,const Element* A,
    int64_t row_base,int64_t k_base,int task,SmemA sA) {
  const int64_t mh=p.m/2,kh=p.k/2;
  const int row=task/(BK/8),k=(task%(BK/8))*8;
  const int64_t gr=row_base+row,gk=k_base+k;
  const auto a11=psplit_sw128_simt_control_root_future41_read_eight(A+gr*p.lda+gk);
  const auto a12=psplit_sw128_simt_control_root_future41_read_eight(A+gr*p.lda+gk+kh);
  const auto a21=psplit_sw128_simt_control_root_future41_read_eight(A+(gr+mh)*p.lda+gk);
  const auto a22=psplit_sw128_simt_control_root_future41_read_eight(A+(gr+mh)*p.lda+gk+kh);
  psplit_sw128_simt_control_root_future41_store_eight(&sA(row,k,0),a11);
  psplit_sw128_simt_control_root_future41_store_eight(&sA(row,k,1),a12);
  psplit_sw128_simt_control_root_future41_store_eight(&sA(row,k,2),a21);
  psplit_sw128_simt_control_root_future41_store_eight(&sA(row,k,3),a22);
}

